import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of each consumer port, with original method/archive comparison. */
public final class CompanionWindDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",A=P+"NativeAreaMaterialAction",B=P+"BattleCompanion",H=P+"NativeCompanionWindAction",S=P+"NativeCompanionWindState";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] method(ClassNode c,MethodNode m,String name,int access){var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;var copy=new MethodNode(access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);q.methods.add(copy);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);q.accept(w);return w.toByteArray();}
 static AbstractInsnNode previous(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode following(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static void before(MethodNode m,AbstractInsnNode n,int count){for(int i=0;i<count;i++)m.instructions.remove(previous(n));}
 static void after(MethodNode m,AbstractInsnNode n,int count){for(int i=0;i<count;i++)m.instructions.remove(following(n));}
 public static void main(String[]args)throws Exception{try(var old=new JarFile(args[0]);var next=new JarFile(args[1])){
  var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var n=next.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed entry");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),next.getInputStream(n).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(next.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(PC+".class",A+".class",B+".class"))||!fresh.equals(Set.of(H+".class",S+".class")))throw new AssertionError("archive boundary");
  int selection=0,admission=0,effect=0,run=0,interval=0,cancel=0,clear=0;
  for(String name:List.of(PC,A,B)){var b=read(old,name);var a=read(next,name);if(name.equals(B)){var added=a.fields.stream().filter(f->f.name.equals("nativeCompanionWindStatus")).findFirst().orElseThrow();if(added.access!=ACC_PRIVATE||!added.desc.equals("L"+P+"BattleWindShackleStatus;"))throw new AssertionError("bounded NPC lease field");a.fields.remove(added);}if(a.fields.size()!=b.fields.size()||a.methods.size()!=b.methods.size()+(name.equals(PC)?1:0))throw new AssertionError("schema");for(int i=0;i<b.fields.size();i++){var x=b.fields.get(i);var y=a.fields.get(i);if(!x.name.equals(y.name)||!x.desc.equals(y.desc)||x.access!=y.access||!Objects.equals(x.value,y.value))throw new AssertionError("original field");}
   for(var original:b.methods){var m=a.methods.stream().filter(v->v.name.equals(original.name)&&v.desc.equals(original.desc)).findFirst().orElseThrow();for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v){
     if(name.equals(PC)&&v.owner.equals(H)){if(!m.name.equals("nativeMaterialAreaWindBody"))throw new AssertionError("167 only");switch(v.name){case "select"->{before(m,n,6);after(m,n,13);m.instructions.remove(n);selection++;}case "admit"->{before(m,n,2);v.owner=A;v.desc=v.desc.replace("J)Z",")Z");admission++;}case "apply"->{before(m,n,9);after(m,n,13);m.instructions.remove(n);effect++;}default->throw new AssertionError("unexpected PC hook");}}
     if(name.equals(A)&&v.owner.equals(H)){if(!m.name.equals("run")||!v.name.equals("run"))throw new AssertionError("run only");v.owner=P+"NativeCompanionForestArea";run++;}
     if(name.equals(B)&&v.owner.equals(S)){if((m.access&ACC_SYNCHRONIZED)==0)throw new AssertionError("actor ownership");switch(v.name){case "interval"->{if(!m.name.equals("beginStrike")||!m.desc.startsWith("(IIIJ"))throw new AssertionError();before(m,n,2);interval++;}case "cancel"->{if(!m.name.equals("cancelMagicEffects"))throw new AssertionError();before(m,n,1);cancel++;}case "clear"->{before(m,n,1);clear++;}default->throw new AssertionError("unknown actor hook");}m.instructions.remove(n);}
    }m.maxLocals=original.maxLocals;if(!Arrays.equals(method(b,original,original.name,original.access),method(a,m,m.name,m.access)))throw new AssertionError("original method changed "+name+"."+m.name);
   }
   if(name.equals(PC)){var origin=b.methods.stream().filter(m->m.name.equals("combatProbability$14")).findFirst().orElseThrow();var alias=a.methods.stream().filter(m->m.name.equals("nativeCompanionWindChance")).findFirst().orElseThrow();if(!Arrays.equals(method(b,origin,origin.name,origin.access),method(a,alias,origin.name,origin.access)))throw new AssertionError("original probability clone");}
  }if(selection!=1||admission!=1||effect!=1||run!=1||interval!=1||cancel!=1||clear!=7)throw new AssertionError("bounded port counts");
  var state=read(next,S);if(state.fields.size()!=1||!state.fields.get(0).name.equals("FIELD")||state.fields.get(0).value==null)throw new AssertionError("stateless state adapter");var action=read(next,H);if(!action.fields.isEmpty())throw new AssertionError("stateless action adapter");for(var c:List.of(state,action))for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW&&(t.desc.contains("Thread")||t.desc.contains("Executor")||t.desc.contains("Map")))throw new AssertionError("new registry/worker");if(n instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("AccountRepository")||v.owner.contains("GameStateStore")||v.owner.contains("Executor")||v.owner.equals("java/lang/Thread")&&!v.name.equals("holdsLock")))throw new AssertionError("IO/lifetime dependency");}
 }System.out.println("PASS three changed classes/two stateless helpers; one actor-owned lazy lease field; exact inverse selection/admit/effect/probability/clock/cancel/seven owned resets; original methods, player schemas, Context, permissions and remaining archive retained");}
}
